arguments.argument:
with(obj_unit)
{
    if choose(0, 1)
    {
        if global.player_com[player] and drag_ok=0 and skil_number>0 and unit_cre_number!=6
        {
            for(i=0; i!=ds_list_size(global.go_moni); i+=1)
            {
                if ds_list_find_value(global.go_moni, i)=unit_id
                {
                    unit_cre_id[unit_cre_number]=skil_id[0]
                    if unit_cre_number=0{unit_cre_time=global.moni_alarm[skil_id[0]]}
                    unit_cre_number+=1
                    break
                }
            }
        }
    }
}

alarm[0]=room_speed*35/global.player_com_ai
